  P=(['keluarga calon mempelai sudah menyebar undangan', 'persiapan perkawinan kedua calon mempelai sudah berjalan'],
     ['rumah calon mempelai sudah dihias', 'lamaran kedua calon mempelai sudah dilaksanakan']),
